#!/usr/bin/env bash
# generated by grippd 0.3.0 from grippd.yaml. Don't edit: change grippd.yaml and grippd regenerates this file.
# Usage: ship.sh artifact <app> <app dir> [assets dir]
#        ship.sh migrations <migrations dir>
#        ship.sh ready
# Uploads this commit's builds to grippd, then tells grippd the commit is ready to ship.
# Needs GRIPPD_UPLOAD_TOKEN from mint.sh. Each upload is accepted once, and only if the
# run's manifest lists it. The upload is the same for every environment, so production
# later runs exactly the bytes staging ran. Migrations are uploaded as files; grippd's
# cloud applies them, never CI.
set -euo pipefail
base="https://grippd-api.grippd.workers.dev/v1/projects/$GRIPPD_PROJECT/commits/$GITHUB_SHA"
auth="Authorization: Bearer $GRIPPD_UPLOAD_TOKEN"

# curl, showing grippd's reason on the run when it refuses the call.
send() {
  local what=$1; shift
  local resp code msg
  resp=$(mktemp)
  code=$(curl -sS -o "$resp" -w '%{http_code}' -H "$auth" "$@")
  if [[ $code != 2* ]]; then
    msg=$(jq -r '(.error | if type == "object" then .message else . end) // .message // empty' "$resp" 2>/dev/null || true)
    echo "::error title=grippd blocked $what::${msg:-HTTP $code}"
    { echo "### grippd blocked $what"; echo; echo "${msg:-HTTP $code}"; } >> "$GITHUB_STEP_SUMMARY"
    exit 1
  fi
}

put() {
  local name=$1 dir=$2
  tar -czf "$dir.tgz" -C "$dir" .
  send "the upload of $name" -X PUT -H "Content-Type: application/gzip" \
    --data-binary "@$dir.tgz" "$base/artifacts/$name"
  echo "Uploaded $name ($(du -h "$dir.tgz" | cut -f1))"
}

case $1 in
  artifact)
    app=$2 dir=$3 assets=${4:-}
    out=$(mktemp -d)
    # Bundle the Worker with its dependencies, so grippd deploys it without node_modules.
    bunx wrangler deploy --dry-run --config "$dir/wrangler.jsonc" --outdir "$out/worker" >/dev/null
    cp "$dir/wrangler.jsonc" "$out/"
    if [[ -n "$assets" ]]; then cp -R "$dir/$assets" "$out/assets"; fi
    put "$app" "$out"
    ;;
  migrations)
    out=$(mktemp -d)
    cp -R "$2" "$out/migrations"
    put migrations "$out"
    ;;
  ready)
    send "handing over $GITHUB_SHA" -X POST "$base/ready"
    echo "Handed $GITHUB_SHA to grippd: infrastructure, migrations, deploys and health checks run there."
    ;;
  *)
    echo "usage: ship.sh artifact|migrations|ready" >&2; exit 2 ;;
esac
